@Test
public void testSimple2() throws Exception {
    Connection conn = ds.getConnection();
    assertNotNull(conn);
    PreparedStatement stmt = conn.prepareStatement("select * from dual");
    assertNotNull(stmt);
    ResultSet rset = stmt.executeQuery();
    assertNotNull(rset);
