        // expected
    }
    conn = ds.getConnection();
    assertNotNull(conn);
    stmt = conn.prepareStatement("select * from dual");
    assertNotNull(stmt);
    rset = stmt.executeQuery();
    assertNotNull(rset);
    assertTrue(rset.next());
    rset.close();
    stmt.close();
    stmt = conn.prepareStatement("select * from dual");
    assertNotNull(stmt);
    rset = stmt.executeQuery();
    assertNotNull(rset);
    assertTrue(rset.next());
    rset.close();
    stmt.close();
    conn.close();
    conn = null;
}

